Object.assign(TXT.en.dir,{name:"K.P Eldho",title:"Chairman",pill:"The chairman",h:"A dream at <em>twenty-one</em>, a company built on <em>trust</em>.",quote:"He arrived in Saudi Arabia at 21 with a dream.",
 bio:["K.P Eldho is the Director of Golden Star Arabia. He is not from Saudi Arabia. He came here at the age of 21 with a dream, and chose to build his life and his business in the Kingdom.","Over the years he built a long-running trading business on honest dealing and hard work. That same spirit runs through Golden Star Arabia today, from the first measurement to the final test.","For him it is about keeping a promise to every customer, every fleet and every family that depends on the work."],
 tl:[{y:"Age 21",t:"Arrives in Saudi Arabia with a dream."},{y:"The early years",t:"Builds a long-running trading business on honest dealing."},{y:"Today",t:"Leads Golden Star Arabia: radiators and truck bodies."}]});
Object.assign(TXT.ar.dir,{name:"ك. ب. إلدهو",title:"رئيس مجلس الإدارة",pill:"رئيس مجلس الإدارة",h:"حلم في الحادية والعشرين، وشركة قامت على الثقة.",quote:"وصل إلى المملكة في الحادية والعشرين بحلم.",
 bio:["ك. ب. إلدهو هو مدير شركة جولدن ستار العربية. ليس من أهل المملكة، فقد جاء إليها وهو في الحادية والعشرين من عمره بحلم، واختار أن يبني حياته وعمله فيها.","وعلى مرّ السنين بنى نشاطاً تجارياً عريقاً على الأمانة والجهد. وتلك الروح نفسها تسري في جولدن ستار العربية اليوم، من أول قياس حتى الاختبار الأخير.","وبالنسبة له الأمر وفاء بوعد لكل عميل ولكل أسطول ولكل أسرة تعتمد على هذا العمل."],
 tl:[{y:"عمر 21",t:"يصل إلى المملكة بحلم."},{y:"السنوات الأولى",t:"يبني نشاطاً تجارياً عريقاً على الأمانة."},{y:"اليوم",t:"يقود جولدن ستار العربية: رادياتيرات وهياكل شاحنات."}]});
