const head=s=>`<div class="head"><div class="rv">${s.h?`<span class="pill">${s.title}</span>`:""}<h2>${s.h||s.title}</h2><div class="rule"></div></div><p class="lead rv">${s.lead}</p></div>`;
const steps=(s,t)=>`<p class="sub">${t}</p><div class="steps rv">${s.map((x,i)=>`<div class="step"><b>${i+1}</b><h3>${x.t}</h3><p>${x.d}</p></div>`).join("")}</div>`;
const split=(x,y,c)=>`<div class="split ${c||""}">${x}${y}</div>`;
const sec=(inner,id,first,cls,bg)=>`<section${id?` id="${id}"`:""} class="${first?"page-top ":""}${cls||""}">${bg?`<div class="pbg"><img src="${bg}" alt=""></div>`:""}<div class="wrap">${inner}</div></section>`;
