<pattern id="fp" width="6" height="9" patternUnits="userSpaceOnUse"><rect width="6" height="9" fill="#767a7d"/><path d="M0 0L3 9L6 0" fill="none" stroke="#eceee9" stroke-width="1.5"/><path d="M1.1 3L2 6.4M4 6.4L4.9 3" stroke="#4d5255" stroke-width=".6"/></pattern>
