const meet=()=>{const d=T().dir;return `<div class="meet rv" id="meet"><div class="photo">${SITE.photo?`<img class="real" src="${SITE.photo}" alt="${d.name}">`:`<img class="ph" src="${$(".nav-logo").src}" alt="">`}<button class="plus" id="plusBtn" aria-expanded="false" aria-label="${d.msg.tag}"></button><div class="mtag">${d.msg.tag}</div></div><div class="mcard"><div class="dtitle cm-k">${d.msg.h}</div><h5 class="cm-q">${d.msg.q}</h5>${d.msg.p.map(x=>`<p>${x}</p>`).join("")}<div class="dname cm-sign">${d.name}</div><div class="dtitle" style="margin:6px 0 4px">${d.title}</div><a class="dlink" href="#/contact">${d.contact}<svg viewBox="0 0 100 8" preserveAspectRatio="none"><path d="M2 5C25 2 50 6 98 3"/></svg></a></div></div>`};
const chalk=()=>{const c=T().chalk;return `<div class="chalk rv" id="chalk"><h3 class="ct">${c.title}</h3><p class="hw sand" style="--d:.2s">${c.n}</p><svg class="arr" viewBox="0 0 80 50"><path pathLength="1" style="--d:.8s" d="M5 4C10 35 40 45 72 40M62 32L74 40L60 46"/></svg><p class="hw" style="--d:1.3s">${c.a}</p><p class="hw" style="--d:1.8s">+</p><p class="hw" style="--d:2.3s">${c.b}<span class="note">${c.c}<svg viewBox="0 0 100 40" preserveAspectRatio="none"><ellipse cx="50" cy="20" rx="48" ry="18"/></svg></span></p><p class="hw" style="--d:2.9s">=</p><p class="hw" style="--d:3.4s">${c.d}</p><svg class="ul" viewBox="0 0 300 20"><path pathLength="1" style="--d:4s" d="M4 12C60 6 140 15 296 7M30 17C110 12 190 18 270 14"/></svg></div>`};

let PRE="",cur=null;
const IMG=ASSETS.img;
const TOUCH=matchMedia("(hover:none)").matches;
const lensDefs=`<defs><linearGradient id="alu" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f4f4ef"/><stop offset=".45" stop-color="#a9adb0"/><stop offset=".7" stop-color="#e6e7e2"/><stop offset="1" stop-color="#7f8488"/></linearGradient><linearGradient id="cool" x1="0" x2="1"><stop offset="0" stop-color="#F2A93B"/><stop offset="1" stop-color="#7FB3D0"/></linearGradient><radialGradient id="lg" cx=".5" cy=".5" r=".7"><stop offset="0" stop-color="#2a2927"/><stop offset="1" stop-color="#141413"/></radialGradient></defs><rect x="-60" y="-60" width="420" height="420" fill="url(#lg)"/>`;
const zig=(y0,y1,x0,x1,st)=>{let d="",l="";for(let x=x0;x<x1;x+=st){d+=`${x===x0?"M":"L"}${x},${y0}L${x+st/2},${y1}`;const m=y1-y0;l+=`M${x+st*.12},${y0+m*.2}L${x+st*.38},${y0+m*.8}M${x+st*.62},${y0+m*.8}L${x+st*.88},${y0+m*.2}`}return `<path d="${d}" class="fin-s"/><path d="${d}" class="fin"/><path d="${l}" class="lv"/>`};
const finsSVG=()=>{let g="";const ys=[8,76,144,212,280];
 for(let i=0;i<4;i++)g+=zig(ys[i]+20,ys[i+1],-60,360,18);
 ys.forEach((y,i)=>{g+=`<rect x="-60" y="${y}" width="420" height="20" rx="10" fill="url(#alu)"/><rect x="-60" y="${y+6}" width="420" height="8" rx="4" fill="#1b1a19"/><line class="fl" x1="-60" y1="${y+10}" x2="360" y2="${y+10}" style="animation-delay:${-i*.4}s"/>`});
 for(let k=0;k<6;k++)g+=`<line class="air" x1="-60" y1="${44+k*24}" x2="360" y2="${44+k*24}" style="animation-delay:${-k*.3}s"/>`;return g};
const tubeSVG=l=>{let g=zig(6,78,-60,360,26)+zig(222,294,-60,360,26);
 g+=`<rect x="-60" y="78" width="420" height="144" fill="url(#alu)"/><rect x="-60" y="102" width="420" height="96" fill="url(#cool)"/>`;
 let w="M-60,150";for(let x=-60;x<360;x+=24)w+=" q6,-40 12,0 t12,0";g+=`<path class="turb" d="${w}"/>`;
 [114,130,170,186].forEach((y,i)=>g+=`<line class="fl2" x1="-60" y1="${y}" x2="360" y2="${y}" style="animation-delay:${-i*.3}s"/>`);
 let d="";const cy=[112,134,160,184];for(let i=0;i<14;i++)d+=`<circle cx="${-60+i*36}" cy="${cy[i%4]}" r="2.2" fill="#fff" opacity=".8"/>`;g+=`<g class="drift">${d}${d.replace(/cx="(-?\d+)"/g,(m,x)=>`cx="${+x+18}"`).replace(/cy="\d+"/g,(m)=>`cy="${cy[(+m.match(/\d+/)[0]+1)%4]}"`)}</g>`;
 for(let x=-47;x<360;x+=26)g+=`<circle cx="${x}" cy="78" r="4" fill="#E0B45C"/><circle cx="${x+13}" cy="222" r="4" fill="#E0B45C"/>`;
 return `<g class="pan">${g}</g><g class="lab"><rect x="8" y="120" width="70" height="16" rx="8"/><text x="43" y="131" text-anchor="middle">${l[2]}</text><rect x="214" y="144" width="78" height="16" rx="8"/><text x="253" y="155" text-anchor="middle">${l[0]}</text><rect x="92" y="60" width="86" height="16" rx="8"/><text x="135" y="71" text-anchor="middle">${l[1]}</text></g>`};
const lensFig=t=>{const L=t.rad.lens;return `<figure class="art lensbox rv" id="lensbox">${radHero(t.rad.labels)}<div class="lens" id="lens"><svg viewBox="0 0 300 300">${lensDefs}<g class="g1"><g class="pan">${finsSVG()}</g></g><g class="g2">${tubeSVG(L.l)}</g></svg><span class="lz" id="lz">${L.z1}</span></div><div class="lhint">${TOUCH&&L.hintT?L.hintT:L.hint}</div><figcaption>${t.rad.caption}</figcaption></figure>`};
const acc=a=>`<div class="acc rv">${a.map((v,i)=>`<div class="acc-i${i?"":" open"}"><button class="acc-b" data-acc><span>${v.t}</span><i></i></button><div class="acc-p"><div><p>${v.d}</p></div></div></div>`).join("")}</div>`;

const lensCol=t=>`<div class="lenscol">${lensFig(t)}<div class="legend rv">${t.rad.legend.map((x,i)=>`<div class="lg-i"><b>${i+1}</b><div><h4>${x.t}</h4><p>${x.d}</p></div></div>`).join("")}</div></div>`;
const itemsPic=(a,im)=>`<div class="list rv">${a.map((i,n)=>`<div class="item pic"><figure class="thumb"><img src="${im[n]}" alt="${i.t}"></figure><div><h3>${i.t}</h3><p>${i.d}</p></div></div>`).join("")}</div>`;
