g.addColorStop(0,`rgba(255,228,165,${.55*f})`);g.addColorStop(.3,`rgba(224,180,92,${.2*f})`);g.addColorStop(1,"rgba(224,180,92,0)");x.fillStyle=g;x.fillRect(0,0,W,H);
if(on)for(let i=0;i<4;i++)spawn();x.lineCap="round";S=S.filter(p=>p.l>0);
